"""执行计划中的动作，并维护清单。

写入采用「同目录临时文件 + 原子替换」：目标位置要么是旧内容，要么是新内容，
不会出现半个文件。

Windows 上文件被占用时不强制失败，而是记录到 deferred 列表，等待下次重试。
不可延迟的错误会触发完整回滚。
"""

import os
import shutil
from collections import namedtuple

from . import manifest, planner
from .errors import ApplyFailed

ApplyResult = namedtuple("ApplyResult", "operation product version applied deferred")

TMP_SUFFIX = ".winstall-part"
BACKUP_SUFFIX = ".winstall-backup"


def _ensure_parent(path):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)


def _put_file(source, destination):
    """把 ``source`` 放到 ``destination``（原子替换）。"""
    temporary = destination + TMP_SUFFIX
    shutil.copyfile(source, temporary)
    os.replace(temporary, destination)


def _delete_file(path):
    if os.path.isfile(path):
        os.remove(path)


def _cleanup_temp_files(payload_root):
    """清理载荷目录下所有的临时文件和备份文件。"""
    if not os.path.isdir(payload_root):
        return
    for root, dirs, files in os.walk(payload_root):
        for name in files:
            if name.endswith(TMP_SUFFIX) or name.endswith(BACKUP_SUFFIX):
                try:
                    os.remove(os.path.join(root, name))
                except OSError:
                    pass


def _backup_file(path):
    """备份文件到同目录下的 .winstall-backup 文件。"""
    if os.path.isfile(path):
        backup_path = path + BACKUP_SUFFIX
        shutil.copyfile(path, backup_path)
        return backup_path
    return None


def _restore_backup(path):
    """从备份恢复文件。"""
    backup_path = path + BACKUP_SUFFIX
    if os.path.isfile(backup_path):
        shutil.copyfile(backup_path, path)
        os.remove(backup_path)


def _remove_backup(path):
    """删除备份文件。"""
    backup_path = path + BACKUP_SUFFIX
    if os.path.isfile(backup_path):
        try:
            os.remove(backup_path)
        except OSError:
            pass


def apply_transaction(plan):
    """顺序执行 ``plan`` 中的动作，然后更新清单。

    Windows 上文件被占用时，该文件会加入 deferred 列表，保持旧内容不变。
    不可延迟的错误会触发完整回滚。
    """
    payload_root = planner.payload_dir(plan.root, plan.product)

    # 读取当前清单，检查是否有待重试的文件
    data = manifest.read_manifest(plan.root)
    current = manifest.get_product(data, plan.product)
    pending_retry = set()
    if current:
        pending_retry = set(current.get("pending_replace") or [])

    applied = []
    deferred = []
    backups = []  # 记录所有备份的文件，用于回滚
    created = []  # 记录本次新建的文件，用于回滚

    try:
        for action in plan.actions:
            target = planner.destination(plan, action)

            if action.kind == "write":
                _ensure_parent(target)

                # 检查目标是否是目录（不可延迟的错误）
                if os.path.isdir(target):
                    raise ApplyFailed(
                        action,
                        "target is a directory, not a file: %s" % action.relpath
                    )

                # 如果文件存在，先备份
                file_existed = os.path.isfile(target)
                if file_existed:
                    backup_path = _backup_file(target)
                    if backup_path:
                        backups.append((target, backup_path))

                # 尝试写入
                try:
                    temporary = target + TMP_SUFFIX
                    shutil.copyfile(action.source, temporary)
                    os.replace(temporary, target)
                    applied.append(action.relpath)

                    # 如果这个文件之前在 pending_replace 里，现在成功了，从集合中移除
                    if action.relpath in pending_retry:
                        pending_retry.discard(action.relpath)

                    # 如果是新创建的文件，记录下来
                    if not file_existed:
                        created.append(target)

                except PermissionError:
                    # 文件被占用，加入 deferred 列表
                    # 恢复备份（如果有）
                    if file_existed:
                        _restore_backup(target)
                        backups.remove((target, target + BACKUP_SUFFIX))
                    # 清理临时文件
                    try:
                        if os.path.isfile(temporary):
                            os.remove(temporary)
                    except OSError:
                        pass
                    deferred.append(action.relpath)
                    # 加入待重试集合
                    pending_retry.add(action.relpath)

            elif action.kind == "remove":
                try:
                    _delete_file(target)
                    applied.append(action.relpath)
                except PermissionError:
                    # remove 操作被占用时也延迟
                    deferred.append(action.relpath)
                    pending_retry.add(action.relpath)
                except OSError:
                    # 文件不存在，视为成功
                    applied.append(action.relpath)

            else:
                raise ValueError("unknown action: %r" % (action.kind,))

        # 所有操作成功或部分延迟，更新清单
        data = manifest.read_manifest(plan.root)
        if plan.operation == planner.INSTALL:
            manifest.set_product(
                data, 
                plan.product, 
                plan.version, 
                plan.files,
                list(pending_retry)
            )
        else:
            if not deferred:
                # 卸载完全成功
                manifest.drop_product(data, plan.product)
            else:
                # 卸载有文件无法删除，保留清单条目但标记 pending_replace
                if current:
                    current["pending_replace"] = list(pending_retry)

        manifest.write_manifest(plan.root, data)

        # 清理所有备份文件
        for target, backup_path in backups:
            _remove_backup(target)

        # 清理载荷目录下的所有临时文件
        _cleanup_temp_files(payload_root)

        return ApplyResult(
            plan.operation, 
            plan.product, 
            plan.version,
            tuple(applied), 
            tuple(deferred)
        )

    except ApplyFailed:
        # ApplyFailed 已经是包装好的异常，直接回滚
        _rollback(backups, created, payload_root)
        raise

    except Exception as e:
        # 不可延迟的错误，回滚
        _rollback(backups, created, payload_root)
        raise ApplyFailed(None, "transaction failed: %s" % str(e))


def _rollback(backups, created, payload_root):
    """回滚所有已执行的操作。"""
    # 恢复所有备份的文件
    for target, backup_path in backups:
        try:
            if os.path.isfile(backup_path):
                shutil.copyfile(backup_path, target)
        except OSError:
            pass

    # 删除所有新创建的文件
    for path in created:
        try:
            if os.path.isfile(path):
                os.remove(path)
        except OSError:
            pass

    # 清理所有临时文件和备份文件
    _cleanup_temp_files(payload_root)

