        data = manifest.read_manifest(plan.root)
        if plan.operation == planner.INSTALL:
            manifest.set_product(
                data, 
                plan.product, 
                plan.version, 
                plan.files,
                list(pending_retry)
            )
        else:
            if not deferred:
                # 卸载完全成功
                manifest.drop_product(data, plan.product)
            else:
                # 卸载有文件无法删除，保留清单条目但标记 pending_replace
                if current:
                    current["pending_replace"] = list(pending_retry)

        manifest.write_manifest(plan.root, data)

        # 清理所有备份文件
        for target, backup_path in backups:
            _remove_backup(target)

        # 清理载荷目录下的所有临时文件
        _cleanup_temp_files(payload_root)

        return ApplyResult(
            plan.operation, 
            plan.product, 
            plan.version,
            tuple(applied), 
            tuple(deferred)
        )

    except ApplyFailed:
        # ApplyFailed 已经是包装好的异常，直接回滚
        _rollback(backups, created, payload_root)
        raise

    except Exception as e:
        # 不可延迟的错误，回滚
        _rollback(backups, created, payload_root)
        raise ApplyFailed(None, "transaction failed: %s" % str(e))


def _rollback(backups, created, payload_root):
    """回滚所有已执行的操作。"""
    # 恢复所有备份的文件
    for target, backup_path in backups:
        try:
            if os.path.isfile(backup_path):
                shutil.copyfile(backup_path, target)
        except OSError:
            pass

    # 删除所有新创建的文件
    for path in created:
        try:
            if os.path.isfile(path):
                os.remove(path)
        except OSError:
            pass

    # 清理所有临时文件和备份文件
    _cleanup_temp_files(payload_root)
